select is(public.entry_relations('93800000-0000-4000-8000-000000000001','candidates','Private foreign')->>'total_count','0','Foreign writing stays private');
select throws_ok($$select public.set_entry_relation('93800000-0000-4000-8000-000000000001','93800000-0000-4000-8000-000000000001',1,true)$$,'22023','invalid_relation_request','Self links refused');
