update public.entries set deleted_at=now() where id='93800000-0000-4000-8000-000000000002';
set local role authenticated;
select is(public.entry_relations('93800000-0000-4000-8000-000000000001')->>'total_count','1','Trash retains the relationship');
select is(public.entry_relations('93800000-0000-4000-8000-000000000001')->'items'->0->>'is_deleted','true','Trash state explicitly labeled');
select is(public.entry_relations('93800000-0000-4000-8000-000000000003','candidates','牙套')->>'total_count','0','New candidate searches omit Trash');
select is(public.set_entry_relation('93800000-0000-4000-8000-000000000003','93800000-0000-4000-8000-000000000002',1,true),null::integer,'Cannot newly link a trashed target');
select is(public.set_entry_relation('93800000-0000-4000-8000-000000000001','93800000-0000-4000-8000-000000000002',2,false),3,'Explicit unlink can remove a retained Trash link');
select is(jsonb_array_length((select snapshot->'links' from public.entry_versions where entry_id='93800000-0000-4000-8000-000000000001' and version=2)),1,'Removed link kept in history');
select throws_ok($$select public.restore_entry_version('93800000-0000-4000-8000-000000000001',2,3)$$,'P0001','history_reference_unavailable','History restore refuses unavailable target');
