select is(public.restore_entry_version('93800000-0000-4000-8000-000000000001',2,3),4,'History restores the link after target restoration');
select is(public.entry_relations('93800000-0000-4000-8000-000000000001')->>'total_count','1','Restored relationship becomes navigable');
