insert into public.entry_links(source_entry_id,target_entry_id,owner_id,relationship) values('93800000-0000-4000-8000-000000000001','93800000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001','exploration_source');
set local role authenticated;
select is(public.set_entry_relation('93800000-0000-4000-8000-000000000001','93800000-0000-4000-8000-000000000002',4,false),5,'Unlink changes ordinary relationship only');
select is((select count(*) from public.entry_links where source_entry_id='93800000-0000-4000-8000-000000000001' and relationship='exploration_source'),1::bigint,'Protected exploration provenance preserved');
select throws_ok($$select public.entry_relations('93800000-0000-4000-8000-000000000001','invalid')$$,'22023','invalid_relation_page','Invalid direction refused');
