select ok(not has_function_privilege('anon','public.set_entry_relation(uuid,uuid,integer,boolean)','execute'),'Anonymous mutations forbidden');
select ok(not has_table_privilege('authenticated','public.entry_links','insert'),'Direct client relationship writes are forbidden');
update public.entries set deleted_at=null where id='93800000-0000-4000-8000-000000000001';
insert into public.entries(id,owner_id,title) select ('93800000-0000-4000-8001-'||lpad(i::text,12,'0'))::uuid,'10000000-0000-0000-0000-000000000001','Related '||i from generate_series(1,100) i;
insert into public.entry_links(source_entry_id,target_entry_id,owner_id) select '93800000-0000-4000-8000-000000000001',('93800000-0000-4000-8001-'||lpad(i::text,12,'0'))::uuid,'10000000-0000-0000-0000-000000000001' from generate_series(1,100) i;
set local role authenticated;
select throws_ok($$select public.set_entry_relation('93800000-0000-4000-8000-000000000001','93800000-0000-4000-8000-000000000002',7,true)$$,'22023','relation_limit','Outgoing relationships share the Goal limit');
select is(public.entry_relations('93800000-0000-4000-8000-000000000001')->>'total_count','100','Count includes all linked Entries beyond first page');
select is(jsonb_array_length(public.entry_relations('93800000-0000-4000-8000-000000000001','outgoing','',20,80)->'items'),20,'Last relationship page remains reachable');
select ok(not has_table_privilege('authenticated','public.entry_links','update'),'Clients cannot rewrite system link provenance');
